def has_cycle(values: list[int], pos: int) -> bool:
    nodes = []
    for value in values:
        node = _node_chain([value])
        if nodes:
            nodes[-1].nxt = node
        nodes.append(node)
    if pos >= 0 and nodes:
        nodes[-1].nxt = nodes[pos]
    slow = fast = nodes[0] if nodes else None
    while fast is not None and fast.nxt is not None:
        slow = slow.nxt
        fast = fast.nxt.nxt
        if slow is fast:
            return True
    return False

